/// <summary>
/// MPJ_22376 Free text invoices by Main account. DCP 30/06/2022
/// The <c>CustInvoiceDP</c> class is the data provider class for the <c>CustInvoice</c>Microsoft SQL
/// Server Reporting Services report.
/// </summary>
[
    SRSReportParameterAttribute(classStr(METFTILinesContract)),
    SRSReportQueryAttribute(queryStr(METFTILines))
]
class METFTILinesDP extends SRSReportDataProviderPreProcessTempDB
{
    CustInvoiceJour custInvoiceJour;
    CustInvoiceTrans custInvoiceTrans;
    CustTrans       custTrans;
    CustTable       custTable;

    DimensionSetEntity DefaultDimension;
    DimensionCombinationEntity LedgerDimension;

    METFTIinesTmp   metFTIinesTmp;
    Name            dimensionFocusName;
    FromDate        fromDate;
    ToDate          toDate;
    OpenPaidBoth    invoiceType;

}

Method.Source:
    /// <summary>
    /// Builds the query that is used to pull the records for the report.
    /// </summary>
    /// <param name="_query">
    /// The report query object to modify.
    /// </param>
    /// <param name="_fromDate">
    /// The from date range parameter of the report.
    /// </param>
    /// <param name="_toDate">
    /// The to date range parameter of the report.
    /// </param>
    /// <param name="_invoiceType">
    /// The invoice type parameter of the report.
    /// </param>
    /// <returns>
    /// The modified query object to use to pull records for the report.
    /// </returns>
    private Query buildQuery(
        Query _query,
        FromDate _fromDate,
        ToDate _toDate,
        OpenPaidBoth _invoiceType)
    {
        QueryBuildDataSource qbdsCustTrans;
        QueryBuildDataSource qbdsCustInvoiceJour;

        // Add the date range on all three data sources to allow SQL to restrict the records as much as possible prior to processing
        _query.dataSourceTable(tableNum(CustInvoiceTable), 1).addRange(fieldNum(CustInvoiceTable, InvoiceDate)).value(queryRange(_fromDate, _toDate));
        _query.dataSourceTable(tableNum(CustInvoiceJour), 1).addRange(fieldNum(CustInvoiceJour, InvoiceDate)).value(queryRange(_fromDate, _toDate));
        _query.dataSourceTable(tableNum(CustInvoiceTrans), 1).addRange(fieldNum(CustInvoiceTrans, InvoiceDate)).value(queryRange(_fromDate, _toDate));
        _query.dataSourceTable(tableNum(CustTrans), 1).addRange(fieldNum(CustTrans, TransDate)).value(queryRange(_fromDate, _toDate));

        if (_invoiceType == OpenPaidBoth::Paid)
        {
            _query.dataSourceTable(tableNum(CustTrans), 1).addRange(fieldNum(CustTrans, Closed)).value(queryRange(_fromDate, _toDate));
        }

        // Add link from CustTrans.AccountNum to CustInvoiceJour.InvoiceAccount since this can not
        // be done in metadata directly. The two data sources are linked through CustInvoiceTrans
        // which does not have an AccountNum field. Without this join there are extra CustTrans records
        // returned that have the same date and invoice ID but *different* accounts.
        qbdsCustInvoiceJour = _query.dataSourceTable(tableNum(CustInvoiceJour), 1);
        qbdsCustTrans       = _query.dataSourceTable(tableNum(CustTrans), 1);
        qbdsCustTrans.addLink(fieldNum(CustInvoiceJour, InvoiceAccount), fieldNum(CustTrans, AccountNum), qbdsCustInvoiceJour.name());

        return _query;
    }

/// <summary>
///    Retrieves the actual data for the report from the temporary table.
/// </summary>
/// <returns>
///    The <c>metFTIinesTmp</c> temporary table.
/// </returns>
[
    SRSReportDataSetAttribute(tablestr(METFTIinesTmp))
]
public metFTIinesTmp getMETFTIinesTmp()
{
    select metFTIinesTmp;
    return metFTIinesTmp;
}

    /// <summary>
    ///    Copies the report parameters from data contract to member variables.
    /// </summary>
    private void getReportParameters()
    {
        METFTILinesContract contract = this.parmDataContract();

        if (contract)
        {
            dimensionFocusName  = contract.parmDimensionFocus();
            fromDate            = contract.parmFromDate();
            toDate              = contract.parmToDate();
            invoiceType         = contract.parmInvoiceType();
        }
    }

    /// <summary>
    ///    Inserts data into the <c>metFTIinesTmp</c> temporary table, which will be used by the report.
    /// </summary>
    /// <remarks>Parameter is used when dimension focus is specified. </remarks>
    protected void insertMetFTIinesTmp()
    {
        this.populateMetFTIinesTmp();

        metFTIinesTmp.insert();
    }

    /// <summary>
    /// Populates data into <c>metFTIinesTmp</c> table.
    /// </summary>
    /// <remarks>Parameter is used when dimension focus is specified. </remarks>
    protected void populatemetFTIinesTmp()
    {
        DimensionDisplayValue   dimensionFocusDisplayValue;
        LedgerDimensionBase     mergedLedgerDimension;
   
        metFTIinesTmp.clear();

        metFTIinesTmp.InvoiceId         = custInvoiceTrans.InvoiceId;
        metFTIinesTmp.InvoiceDate       = custInvoiceTrans.InvoiceDate;
        metFTIinesTmp.OrderAccount      = custInvoiceJour.OrderAccount;
        metFTIinesTmp.OrderAccountName  = custTable.name();
        metFTIinesTmp.CustClassification = custTable.CustClassificationId;
        metFTIinesTmp.MainAccountDisplay = LedgerDimension.DisplayValue; 
        metFTIinesTmp.DefaultDimensionsDisplay = DefaultDimension.DisplayValue;
        metFTIinesTmp.Description       = custInvoiceTrans.Name;
        metFTIinesTmp.Quantity          = custInvoiceTrans.Qty;
        metFTIinesTmp.UnitPrice         = custInvoiceTrans.SalesPrice;
        metFTIinesTmp.TaxAmountMST      = custInvoiceTrans.TaxAmountMST;
        metFTIinesTmp.LineAmountMST     = custInvoiceTrans.LineAmountMST;
        metFTIinesTmp.GrossLineAmountMST = metFTIinesTmp.TaxAmountMST + metFTIinesTmp.LineAmountMST;
        
        metFTIinesTmp.CurrencyCode      = custInvoiceTrans.CurrencyCode;

        if(dimensionFocusName && custInvoiceTrans.DefaultDimension && custInvoiceTrans.LedgerDimension)
        {
            try
            {
                mergedLedgerDimension = METHelper::createLedgerDimFromLedgerDefaultDimensions(custInvoiceTrans.DefaultDimension, custInvoiceTrans.LedgerDimension);
            
                dimensionFocusDisplayValue = DimensionSet::getDisplayValueForDimensionSetName(mergedLedgerDimension, dimensionFocusName);
            }
            catch
            {
                dimensionFocusDisplayValue = "";
            }
        }
        
        metFTIinesTmp.DimensionFocusDisplayValue = dimensionFocusDisplayValue;
    }

    /// <summary>
    ///    Retrieves records based on the parameter values and inserts the records into the temporary table.
    /// </summary>
    public void processReport()
    {
        QueryRun queryRun;

        this.getReportParameters();

        queryRun = new QueryRun(this.buildQuery(this.parmQuery(), fromDate, toDate, invoiceType));

        while (queryRun.next())
        {
            custInvoiceJour     = queryRun.get(tableNum(CustInvoiceJour));
            custInvoiceTrans    = queryRun.get(tableNum(CustInvoiceTrans));
            custTrans           = queryRun.get(tableNum(CustTrans));
            custTable           = queryRun.get(tableNum(CustTable));
            DefaultDimension    = queryRun.get(tableNum(DimensionSetEntity));
            LedgerDimension     = queryRun.get(tableNum(DimensionCombinationEntity));
                
            this.insertMetFTIinesTmp();
        }
    }

public static CustInvoiceDP construct()
{
    return new CustInvoiceDP();
}
